INSERT INTO event VALUES(8,1,8,'context.blob',1,'["golden-host",1,"process-1"]',1767225608000,'{"payload":{"digest":"e91e224d8b27d5a42793b4de78c4187a549fd99bab9ee5c2bd43e62cd7aff0c1","value":"{\"description\":\"Read and return workspace files. For text files you can supply an optional line range. PDFs (.pdf) and common image formats are returned as attachments so vision-capable models can inspect their pages or visual content.\",\"name\":\"read_file\",\"parameters\":{\"properties\":{\"path\":{\"description\":\"Workspace-relative or absolute file path to read.\",\"type\":\"string\"},\"range\":{\"anyOf\":[{\"properties\":{\"end\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Last line to read, inclusive and 1-indexed.\"},\"start\":{\"description\":\"First line to read, 1-indexed.\",\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"start\"],\"type\":\"object\"},{\"items\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}]}]},\"maxItems\":2,\"minItems\":1,\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"Optional inclusive line range to read.\"}},\"required\":[\"path\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(9,1,9,'context.blob',1,'["golden-host",1,"process-1"]',1767225609000,'{"payload":{"digest":"b3b2a3d44f4a95de0455196ad7ead418771471fafd4c8ed975d4774b7c4fe2a1","value":"{\"description\":\"Propose or replace the plan: `objective` is a plain document stating what to achieve, the intended approach, and a verifiable stopping condition. Every proposal is presented to the user, who may approve it, run it as a goal (a goal run then works on it in rounds until it verifies the stopping condition), or reject it. Propose a new plan only when the objective or approach genuinely changes.\",\"name\":\"plan\",\"parameters\":{\"properties\":{\"objective\":{\"description\":\"The plan document: what to achieve, the intended approach, and a verifiable stopping condition. Plain prose or markdown - no structured steps.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"objective\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(10,1,10,'context.blob',1,'["golden-host",1,"process-1"]',1767225610000,'{"payload":{"digest":"af931a081959b3a5605e02ff5d932cf1c81253c2e9f2e748503c0f0c967c9255","value":"{\"description\":\"Run a named agent as a child of this run: it works with its own tools on the prompt you give it.\\n\\nFrom a script, `agent(prompt, opts)` (the same as `tools.agent({ prompt, ...opts })`) waits for the child and resolves to its result: `{ response, files, structured?, runId, outcome, cost, spent }`: `cost` is what the child and its own children spent, `spent` what this run has spent in all so far. It rejects with an Error named `AgentFailed`, `TimedOut`, or `Skipped` (the user stopped the child). With `background: true` it resolves to `{ runId }` at once and the result arrives as a follow-up. A completed call is reused, not run again, by a later call in this run with the same prompt, options and file contents; give two otherwise identical calls of one script distinct `id`s.\\n\\nCalled directly, the child runs in the background and its result arrives as a follow-up message; in a one-shot run the call waits for it.\\n\\nIt returns the agent''s final reply, or a `schema` value. Pick the agent whose description fits the task.\",\"name\":\"agent\",\"parameters\":{\"properties\":{\"agentName\":{\"description\":\"The agent to run. It works with its own tools.\",\"minLength\":1,\"type\":\"string\"},\"background\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"In a script: return `{ runId }` at once; the result arrives as a follow-up. A direct call always runs in the background, except in a one-shot run.\"},\"id\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Tells apart two otherwise identical calls: a completed call is reused by a later one with the same prompt, options and files.\"},\"label\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"A short title for the call’s card.\"},\"mediaFiles\":{\"anyOf\":[{\"items\":{\"type\":\"string\"},\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"Images, figures, PDFs or audio attached to the prompt.\"},\"memories\":{\"anyOf\":[{\"items\":{\"type\":\"string\"},\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"Memory file paths to attach (e.g. /memories/conventions.md). Content is injected into the agent prompt as read-only context. Use for project conventions, style guides, or accumulated knowledge the agent should follow.\"},\"model\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Model reference, `@effort` suffix allowed (`@low` … `@max`, `@none`). Defaults to your current model when available.\"},\"persona\":{\"anyOf\":[{\"properties\":{\"prompt\":{\"description\":\"Its system prompt: who it is and how it works.\",\"minLength\":1,\"type\":\"string\"},\"tools\":{\"anyOf\":[{\"items\":{\"minLength\":1,\"type\":\"string\"},\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"The tools it gets, by name; omitted, none. It gets only those you have.\"}},\"required\":[\"prompt\"],\"type\":\"object\"},{\"type\":\"null\"}],\"description\":\"Define the agent here, named `agentName`, instead of naming one from the catalog: for this call alone.\"},\"prompt\":{\"description\":\"The task, in plain prose. Name the files it concerns and copy every constraint the agent must follow: it does not see your conversation.\",\"minLength\":1,\"type\":\"string\"},\"schema\":{\"anyOf\":[{\"type\":\"object\"},{\"type\":\"null\"}],\"description\":\"A JSON Schema object: the agent finishes by submitting a value of it, returned as `structured`.\"},\"timeoutMs\":{\"anyOf\":[{\"maximum\":86400000,\"minimum\":1000,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Stops the agent after this many milliseconds: `TimedOut`.\"},\"working_directory\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Absolute path for the subagent to operate in (e.g. a git worktree). All tool calls within the subagent will automatically use this as their root directory. Defaults to workspace root. Only accepted when git worktree support (`git.worktreeSupport`) is enabled for this workspace.\"}},\"required\":[\"prompt\",\"agentName\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(11,1,11,'context.blob',1,'["golden-host",1,"process-1"]',1767225611000,'{"payload":{"digest":"8ea538b5c480f74c8888f651a28bbbda43ba681454f2b767cd5ca71d6d1a6c73","value":{"$b":"289ae04e81e259ea6f6d169e61ea06039e054de136c4fb0dd2fa0037f99b8ea2"}}}');
INSERT INTO event VALUES(12,1,12,'context.blob',1,'["golden-host",1,"process-1"]',1767225612000,'{"payload":{"digest":"f29a8779b1be7ec8d021f32302282a82b9b1f77f198395da5363cac5337b6f12","value":"{\"description\":\"Manage persistent memory files under /memories (view, create, str_replace, insert, delete, rename, pin, unpin).\\n\\n`view` with no path defaults to the /memories root listing; `rename` uses old_path/new_path instead of path; all other commands require path.\\nDirectory listings are paginated: use offset/limit to page through results (default: offset 0, limit 100).\\n\\nUse `pin` to mark a memory as a core long-term insight (techniques, strategies, pitfalls, best practices). Pinned memories are always loaded at session start. Use `unpin` to remove the pinned status. Maximum 10 pinned memories allowed.\",\"name\":\"memory\",\"parameters\":{\"properties\":{\"command\":{\"enum\":[\"view\",\"create\",\"str_replace\",\"insert\",\"delete\",\"rename\",\"pin\",\"unpin\"],\"type\":\"string\"},\"file_text\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"create\\\".\"},\"insert_line\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"insert\\\".\"},\"insert_text\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"insert\\\": Text to insert. Aliased by `new_str` if omitted.\"},\"limit\":{\"anyOf\":[{\"maximum\":200,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Max entries to return from directory listing. Default: 100, max: 200.\"},\"new_path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"rename\\\": Path under /memories (e.g. /memories/notes.md).\"},\"new_str\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"str_replace\\\" or \\\"insert\\\".\"},\"offset\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Zero-based offset into the directory listing. Use with limit for pagination. Default: 0.\"},\"old_path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"rename\\\": Path under /memories (e.g. /memories/notes.md).\"},\"old_str\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"str_replace\\\".\"},\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Path under /memories (e.g. /memories/notes.md). Defaults to the /memories root directory listing when omitted. With command \\\"create\\\", \\\"str_replace\\\", \\\"insert\\\", \\\"delete\\\", \\\"pin\\\", or \\\"unpin\\\": Path under /memories (e.g. /memories/notes.md).\"},\"view_range\":{\"anyOf\":[{\"items\":{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},\"maxItems\":2,\"minItems\":2,\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\".\"}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
