INSERT INTO event VALUES(166,4,7,'context.blob',1,'["golden-host",3,"process-3"]',1767225766000,'{"payload":{"digest":"bb2f8d9ba8616d9f4e3334f8ff02179561e67d674375573a0c10a44c469cbd20","value":"{\"sections\":{\"core plugin\":\"Find the project''s TeX sources with relative paths (e.g., `find . -name \\\"*.tex\\\"`).\\nFor math in responses, use $...$ or \\\\(...\\\\) for inline and $$...$$ or \\\\[...\\\\] for display math. Wrap LaTeX environments like align or gather inside $$...$$ (e.g., $$\\\\begin{align}...\\\\end{align}$$) so they render correctly.\",\"memory-workflow plugin\":\"<memory_tool_instructions>\\nPinned memories are always loaded unless the user forbids memory use. At session start, `view` the `/memories` directory to find entries marked [pinned]. If the listing is truncated, continue until you have seen every [pinned] entry. Then `view` each pinned file so its content applies, regardless of how self-contained the request looks. Pinned entries are the core reusable insights (techniques, strategies, pitfalls) accumulated across sessions. The directory listing alone does not load their content. Beyond pinned entries, use memory when the request may depend on prior sessions, durable user preferences, or shared agent context. For a self-contained request, do not read unpinned memory files or write memory merely because the tool is available. Listing the directory is still appropriate because it is needed to find pinned entries.\\n\\nYour memory persists across conversations. When memory is in play, record durable progress, decisions, and user preferences (writing style, conventions, formatting, workflow). Keep the folder current and organized by updating, renaming, or deleting files rather than duplicating them. Do not store what the workspace files already state. When project context, coding patterns, or conventions are relevant to the task and git is available, look into git history (commit messages, PR descriptions, recent changes) to understand them. Use `pin` only for long-term reusable insights, never task-specific progress notes. Use `unpin` for entries that no longer earn their place.\\n</memory_tool_instructions>\",\"tool-call\":\"When using a tool, follow the JSON schema exactly and include all required properties.\\nAlways produce valid JSON when calling a tool.\\nDo not call tools that are not provided or any multi_tool_use variants.\\nCall tools sequentially and wait for the output before calling another.\"},\"tools\":[\"read_file\",\"glob\",\"grep\",\"extract_figures\",\"extract_bib_entries\",\"extract_tikz_figures\",\"arxiv_search\",\"memory\"]}"}}');
INSERT INTO event VALUES(167,4,8,'context.blob',1,'["golden-host",3,"process-3"]',1767225767000,'{"payload":{"digest":"e91e224d8b27d5a42793b4de78c4187a549fd99bab9ee5c2bd43e62cd7aff0c1","value":"{\"description\":\"Read and return workspace files. For text files you can supply an optional line range. PDFs (.pdf) and common image formats are returned as attachments so vision-capable models can inspect their pages or visual content.\",\"name\":\"read_file\",\"parameters\":{\"properties\":{\"path\":{\"description\":\"Workspace-relative or absolute file path to read.\",\"type\":\"string\"},\"range\":{\"anyOf\":[{\"properties\":{\"end\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Last line to read, inclusive and 1-indexed.\"},\"start\":{\"description\":\"First line to read, 1-indexed.\",\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"start\"],\"type\":\"object\"},{\"items\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}]}]},\"maxItems\":2,\"minItems\":1,\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"Optional inclusive line range to read.\"}},\"required\":[\"path\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(168,4,9,'context.blob',1,'["golden-host",3,"process-3"]',1767225768000,'{"payload":{"digest":"f18ee2e64cd3535ce04301c5d2f6f987456a5f36a9241d4e970ee31b5a7bc948","value":"{\"description\":\"Find files matching glob patterns (e.g., \\\"**/*.tex\\\", \\\"src/**/*.ts\\\"). Returns paths sorted by modification time.\",\"name\":\"glob\",\"parameters\":{\"properties\":{\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Directory to search within. Defaults to the workspace root.\"},\"pattern\":{\"description\":\"Glob pattern to match, such as \\\"**/*.tex\\\" or \\\"src/**/*.ts\\\".\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"pattern\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(169,4,10,'context.blob',1,'["golden-host",3,"process-3"]',1767225769000,'{"payload":{"digest":"e33e315e319136cfd53b1b176fb81918ef47e2c3b7dea15c8b5308114d414204","value":"{\"description\":\"Search file contents using regex patterns. For surrounding lines use -C with output_mode \\\"content\\\".\",\"name\":\"grep\",\"parameters\":{\"properties\":{\"-A\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Lines of context AFTER each match (only with output_mode \\\"content\\\").\"},\"-B\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Lines of context BEFORE each match (only with output_mode \\\"content\\\").\"},\"-C\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Lines of context before AND after each match.\"},\"-i\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Case-insensitive search.\"},\"-n\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Show line numbers.\"},\"glob\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Glob filter for file names (e.g. \\\"*.tex\\\").\"},\"head_limit\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Limit to first N results.\"},\"literal\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Exact string, not regex.\"},\"multiline\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Enable multiline matching (pattern can span lines).\"},\"offset\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Skip first N results.\"},\"output_mode\":{\"anyOf\":[{\"enum\":[\"content\",\"files_with_matches\",\"count\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Must be \\\"content\\\", \\\"files_with_matches\\\", or \\\"count\\\". For context lines around matches, use -C instead.\"},\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"File or directory to search in.\"},\"pattern\":{\"description\":\"Regex pattern.\",\"minLength\":1,\"type\":\"string\"},\"type\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Ripgrep file type filter (e.g. \\\"tex\\\", \\\"py\\\").\"}},\"required\":[\"pattern\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(170,4,11,'context.blob',1,'["golden-host",3,"process-3"]',1767225770000,'{"payload":{"digest":"d54e73ac7b8744b4b927b950649a743d57b73d6947ff7ffbe35041834aab80ac","value":"{\"description\":\"Resolve and list figure assets referenced by a LaTeX document, returning attachments when available.\",\"name\":\"extract_figures\",\"parameters\":{\"properties\":{\"texPath\":{\"description\":\"Path to the primary LaTeX file to inspect.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"texPath\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(171,4,12,'context.blob',1,'["golden-host",3,"process-3"]',1767225771000,'{"payload":{"digest":"2f00f27a26493629924ea4666f06bb87d6051fbb70585a443b2a83707fa914b2","value":"{\"description\":\"Collect BibTeX records for citations referenced in a LaTeX document.\",\"name\":\"extract_bib_entries\",\"parameters\":{\"properties\":{\"bibPath\":{\"anyOf\":[{\"description\":\"Optional path to a BibTeX file to include when resolving citations.\",\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}]},\"texPath\":{\"description\":\"Path to the LaTeX file to scan for citations.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"texPath\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(172,4,13,'context.blob',1,'["golden-host",3,"process-3"]',1767225772000,'{"payload":{"digest":"0b6ed9f3ed35026c261506cd63bd1a16d155498c2cfbd13319efacf9b28e5d10","value":"{\"description\":\"Discover TikZ figures inside a LaTeX document and optionally compile them into standalone PDFs.\",\"name\":\"extract_tikz_figures\",\"parameters\":{\"properties\":{\"compile\":{\"anyOf\":[{\"description\":\"Compile extracted TikZ pictures into standalone PDFs.\",\"type\":\"boolean\"},{\"type\":\"null\"}]},\"texPath\":{\"description\":\"Path to the LaTeX file containing TikZ figures.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"texPath\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(173,4,14,'context.blob',1,'["golden-host",3,"process-3"]',1767225773000,'{"payload":{"digest":"a146ff8f2543030ca3e39ea816c65cdc53c5c5f78cf9c8d027dda8a80b5a2601","value":"{\"description\":\"Search arXiv for papers and return basic metadata for each hit. Use field=\\\"author\\\" for author name searches.\",\"name\":\"arxiv_search\",\"parameters\":{\"properties\":{\"categories\":{\"anyOf\":[{\"items\":{\"type\":\"string\"},\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"Optional arXiv category filters, exactly as arXiv spells them, such as \\\"math.NT\\\", \\\"cs.AI\\\" or \\\"quant-ph\\\". A paper matches when it is in all of them.\"},\"field\":{\"anyOf\":[{\"enum\":[\"all\",\"author\",\"title\",\"abstract\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Search field: \\\"author\\\" for author names, \\\"title\\\" for paper titles, \\\"abstract\\\" for abstracts, \\\"all\\\" (default) for all fields\"},\"maxResults\":{\"anyOf\":[{\"exclusiveMinimum\":0,\"maximum\":50,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Maximum number of papers to return.\"},\"query\":{\"description\":\"Search query terms, title text, or author names.\",\"type\":\"string\"},\"sortBy\":{\"anyOf\":[{\"enum\":[\"relevance\",\"lastUpdatedDate\",\"submittedDate\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"arXiv sort field to use.\"},\"sortOrder\":{\"anyOf\":[{\"enum\":[\"ascending\",\"descending\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Sort direction for results.\"},\"start\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Zero-based result offset for pagination.\"}},\"required\":[\"query\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(174,4,15,'context.blob',1,'["golden-host",3,"process-3"]',1767225774000,'{"payload":{"digest":"f29a8779b1be7ec8d021f32302282a82b9b1f77f198395da5363cac5337b6f12","value":"{\"description\":\"Manage persistent memory files under /memories (view, create, str_replace, insert, delete, rename, pin, unpin).\\n\\n`view` with no path defaults to the /memories root listing; `rename` uses old_path/new_path instead of path; all other commands require path.\\nDirectory listings are paginated: use offset/limit to page through results (default: offset 0, limit 100).\\n\\nUse `pin` to mark a memory as a core long-term insight (techniques, strategies, pitfalls, best practices). Pinned memories are always loaded at session start. Use `unpin` to remove the pinned status. Maximum 10 pinned memories allowed.\",\"name\":\"memory\",\"parameters\":{\"properties\":{\"command\":{\"enum\":[\"view\",\"create\",\"str_replace\",\"insert\",\"delete\",\"rename\",\"pin\",\"unpin\"],\"type\":\"string\"},\"file_text\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"create\\\".\"},\"insert_line\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"insert\\\".\"},\"insert_text\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"insert\\\": Text to insert. Aliased by `new_str` if omitted.\"},\"limit\":{\"anyOf\":[{\"maximum\":200,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Max entries to return from directory listing. Default: 100, max: 200.\"},\"new_path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"rename\\\": Path under /memories (e.g. /memories/notes.md).\"},\"new_str\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"str_replace\\\" or \\\"insert\\\".\"},\"offset\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Zero-based offset into the directory listing. Use with limit for pagination. Default: 0.\"},\"old_path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"rename\\\": Path under /memories (e.g. /memories/notes.md).\"},\"old_str\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"str_replace\\\".\"},\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Path under /memories (e.g. /memories/notes.md). Defaults to the /memories root directory listing when omitted. With command \\\"create\\\", \\\"str_replace\\\", \\\"insert\\\", \\\"delete\\\", \\\"pin\\\", or \\\"unpin\\\": Path under /memories (e.g. /memories/notes.md).\"},\"view_range\":{\"anyOf\":[{\"items\":{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},\"maxItems\":2,\"minItems\":2,\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\".\"}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
