INSERT INTO event VALUES(199,5,1,'run.start',4,'["golden-host",4,"process-4"]',1767225799000,'{"identity":{"kind":"agent","agent":"polish"},"takesFollowUps":false,"worktree":{"workingDirectory":"/golden/project"},"parent":null,"provenance":null,"approvalPolicy":{"own":{},"goal":[],"limit":"never"}}');
INSERT INTO event VALUES(200,5,2,'run.config',6,'["golden-host",4,"process-4"]',1767225800000,'{"config":{"inputFiles":["paper.tex"],"contextFiles":[],"mediaFiles":[],"outputFiles":[],"editedFile":null,"agent":"polish","agentSource":"builtIn","model":"openai/gpt-5.6-sol","instruction":"","memories":[],"workingDirectory":"/golden/project","cli":{"outputFile":"/golden/project/paper.polished.tex"},"script":{"code":"const agentName = \"builtIn:polish\";\nlet revisions = 1;\nlet critique = null;\nfor (let revision = 0; revision < revisions; revision += 1) {\n  phase(`Revision ${revision + 1}`);\n  const context = await tools.document_context({ revision, critique });\n  revisions = context.revisions;\n  const reply = await agent(context.prompt, {\n    agentName,\n    mediaFiles: context.mediaFiles,\n    memories: context.memories,\n    label: `Revision ${revision + 1}`,\n  });\n  await tools.document_extract({ revision, run: reply.runId });\n  await tools.document_compile({ revision });\n  await tools.document_diff({ revision });\n  if (context.reflect && revision + 1 < revisions) {\n    const review = await tools.document_review({ revision });\n    const critic = await agent(review.prompt, {\n      agentName: ''builtIn:critic'',\n      label: `Critique ${revision + 1}`,\n    });\n    critique = critic.response;\n  }\n}\nawait tools.document_propose({});","title":"polish","tools":["agent","document_context","document_extract","document_compile","document_diff","document_review","document_propose"],"kind":"recipe","block":"task","options":{"attachTeXCount":false,"reflect":false,"autoExtractFigure":false,"autoExtractTikzFigure":false,"autoCompileInputPdf":false}}}}');
