INSERT INTO event VALUES(204,5,6,'context.blob',1,'["golden-host",4,"process-4"]',1767225804000,'{"payload":{"digest":"563b252b1e8e120be9906f0f39ab8c0b8a518265731d7025d501d627901109c5","value":{"$b":"fa2dbad18f9db70d99603aa9d2121da5dd13ebfc4490c4220c6990836cb4af8e"}}}');
INSERT INTO event VALUES(205,5,7,'context.blob',1,'["golden-host",4,"process-4"]',1767225805000,'{"payload":{"digest":"af931a081959b3a5605e02ff5d932cf1c81253c2e9f2e748503c0f0c967c9255","value":"{\"description\":\"Run a named agent as a child of this run: it works with its own tools on the prompt you give it.\\n\\nFrom a script, `agent(prompt, opts)` (the same as `tools.agent({ prompt, ...opts })`) waits for the child and resolves to its result: `{ response, files, structured?, runId, outcome, cost, spent }`: `cost` is what the child and its own children spent, `spent` what this run has spent in all so far. It rejects with an Error named `AgentFailed`, `TimedOut`, or `Skipped` (the user stopped the child). With `background: true` it resolves to `{ runId }` at once and the result arrives as a follow-up. A completed call is reused, not run again, by a later call in this run with the same prompt, options and file contents; give two otherwise identical calls of one script distinct `id`s.\\n\\nCalled directly, the child runs in the background and its result arrives as a follow-up message; in a one-shot run the call waits for it.\\n\\nIt returns the agent''s final reply, or a `schema` value. Pick the agent whose description fits the task.\",\"name\":\"agent\",\"parameters\":{\"properties\":{\"agentName\":{\"description\":\"The agent to run. It works with its own tools.\",\"minLength\":1,\"type\":\"string\"},\"background\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"In a script: return `{ runId }` at once; the result arrives as a follow-up. A direct call always runs in the background, except in a one-shot run.\"},\"id\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Tells apart two otherwise identical calls: a completed call is reused by a later one with the same prompt, options and files.\"},\"label\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"A short title for the call’s card.\"},\"mediaFiles\":{\"anyOf\":[{\"items\":{\"type\":\"string\"},\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"Images, figures, PDFs or audio attached to the prompt.\"},\"memories\":{\"anyOf\":[{\"items\":{\"type\":\"string\"},\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"Memory file paths to attach (e.g. /memories/conventions.md). Content is injected into the agent prompt as read-only context. Use for project conventions, style guides, or accumulated knowledge the agent should follow.\"},\"model\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Model reference, `@effort` suffix allowed (`@low` … `@max`, `@none`). Defaults to your current model when available.\"},\"persona\":{\"anyOf\":[{\"properties\":{\"prompt\":{\"description\":\"Its system prompt: who it is and how it works.\",\"minLength\":1,\"type\":\"string\"},\"tools\":{\"anyOf\":[{\"items\":{\"minLength\":1,\"type\":\"string\"},\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"The tools it gets, by name; omitted, none. It gets only those you have.\"}},\"required\":[\"prompt\"],\"type\":\"object\"},{\"type\":\"null\"}],\"description\":\"Define the agent here, named `agentName`, instead of naming one from the catalog: for this call alone.\"},\"prompt\":{\"description\":\"The task, in plain prose. Name the files it concerns and copy every constraint the agent must follow: it does not see your conversation.\",\"minLength\":1,\"type\":\"string\"},\"schema\":{\"anyOf\":[{\"type\":\"object\"},{\"type\":\"null\"}],\"description\":\"A JSON Schema object: the agent finishes by submitting a value of it, returned as `structured`.\"},\"timeoutMs\":{\"anyOf\":[{\"maximum\":86400000,\"minimum\":1000,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Stops the agent after this many milliseconds: `TimedOut`.\"},\"working_directory\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Absolute path for the subagent to operate in (e.g. a git worktree). All tool calls within the subagent will automatically use this as their root directory. Defaults to workspace root. Only accepted when git worktree support (`git.worktreeSupport`) is enabled for this workspace.\"}},\"required\":[\"prompt\",\"agentName\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(206,5,8,'context.blob',1,'["golden-host",4,"process-4"]',1767225806000,'{"payload":{"digest":"2e136525e5730ec285b62aca6871d0f2c84f9dd68bf68590a12d1b4f811188d4","value":"{\"description\":\"A document task''s revision prompt: the task''s documents, every earlier request with the reply it got, and this revision''s request with the compile failures that rejected the last one and the `critique` of it, if any. Resolves to `{ prompt, mediaFiles, memories, revisions, reflect }`: `memories` are the launch''s, for the revision''s agent; `reflect` says the task reviews each revision but the last (`document_review`).\",\"name\":\"document_context\",\"parameters\":{\"properties\":{\"critique\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"The critic''s review of the last revision.\"},\"revision\":{\"description\":\"The revision, from 0, in the order the task runs them.\",\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"}},\"required\":[\"revision\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(207,5,9,'context.blob',1,'["golden-host",4,"process-4"]',1767225807000,'{"payload":{"digest":"77c016caef7076a3784a3cca38dff1523aca1c3d4437d65c285fdf996040fdb2","value":"{\"description\":\"Take the documents out of the reply a revision''s agent run gave (`run`, the run id `agent()` resolved with): they become the revision''s output files, with their lineage and diff stats. Resolves to `{ files, missing }`: `missing` names the expected files the revision lacks, and `<unextracted document N>` for each document its reply held that did not extract.\",\"name\":\"document_extract\",\"parameters\":{\"properties\":{\"revision\":{\"description\":\"The revision, from 0, in the order the task runs them.\",\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},\"run\":{\"description\":\"The revision''s agent run.\",\"minLength\":3,\"type\":\"string\"}},\"required\":[\"revision\",\"run\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(208,5,10,'context.blob',1,'["golden-host",4,"process-4"]',1767225808000,'{"payload":{"digest":"7bf4e44be734d2f526737156ad8099204875a2c1957f6f4b7152aa98885f3b11","value":"{\"description\":\"Compile a revision''s .tex outputs. Resolves to `{ failures, skipped, rejected }`: the outputs that failed with their logs; why no check ran (auto-compile is off, no .tex output, no LaTeX compiler, or the check failed), else null; and whether the failures reject the revision, which the next revision''s prompt and `document_propose` act on. Run it before `document_diff`, not beside it: each call records the run''s documents whole.\",\"name\":\"document_compile\",\"parameters\":{\"properties\":{\"revision\":{\"description\":\"The revision, from 0, in the order the task runs them.\",\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"}},\"required\":[\"revision\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(209,5,11,'context.blob',1,'["golden-host",4,"process-4"]',1767225809000,'{"payload":{"digest":"7eeb99b9eed4d292dd3ffb2ba2ea567b5e3ff4ba2f7882e6e72136c8217ba6d5","value":"{\"description\":\"Run latexdiff of a revision''s outputs against the documents the task started from. Resolves to `{ diffs, failed, notRun }`: the diff files it wrote, the documents whose diff failed with why (latexdiff not installed among them), and why no diff ran at all (no outputs, or the pass failed), else null. Run it after `document_compile`, not beside it: each call records the run''s documents whole.\",\"name\":\"document_diff\",\"parameters\":{\"properties\":{\"revision\":{\"description\":\"The revision, from 0, in the order the task runs them.\",\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"}},\"required\":[\"revision\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(210,5,12,'context.blob',1,'["golden-host",4,"process-4"]',1767225810000,'{"payload":{"digest":"234ec8542b5e98b031954478c981b4b1caa43e53a9421c135b5976d5dbcc4163","value":"{\"description\":\"The evidence a critic reviews for a revision: the user''s instruction, the task''s requests so far, the diff of each output against the document it started from, and the compile result. Resolves to `{ prompt }`, to pass to the `critic` agent.\",\"name\":\"document_review\",\"parameters\":{\"properties\":{\"revision\":{\"description\":\"The revision, from 0, in the order the task runs them.\",\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"}},\"required\":[\"revision\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(211,5,13,'context.blob',1,'["golden-host",4,"process-4"]',1767225811000,'{"payload":{"digest":"58a974870ba4a8a1280e7e7dbe69e6ef049531b570c2593cdc690209201364cd","value":"{\"description\":\"End the document task: propose the outputs of its latest revision that wrote any for the user to accept, with their diffs against the documents they started from. Fails, naming the failed outputs, when that revision did not compile and failed compiles are rejected. Resolves to `{ files }`, the proposed files; the task''s documents, diffs included, are what its run reports.\",\"name\":\"document_propose\",\"parameters\":{\"properties\":{},\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(212,5,14,'context.blob',1,'["golden-host",4,"process-4"]',1767225812000,'{"payload":{"digest":"11d3e253f5eca8dd45bc07bb321641bd3fc8ce12055a38667b77b6ea56638bf2","value":"{\"description\":\"Run yourself again on a prompt, as a child of this call, and wait for its result: `{ response, files, structured?, runId, outcome, cost, spent }`, as `agent()` resolves.\\n\\nForked (the default), the child continues this conversation as it stood when the script started (the message of the turn that started it, not that turn''s work so far), with `prompt` added to that message; with `fork: false` it starts with no earlier conversation. Either way the child is told `prompt` is the one part of the script''s work it does, and not to take on the rest. It is you with your tools and model: nothing is proposed or approved again. It rejects with an Error named `AgentFailed` or `Skipped` (the user stopped it). Call it from a script; called directly, it runs nothing.\",\"name\":\"self\",\"parameters\":{\"properties\":{\"fork\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Continue this conversation as it stood when the script started, with `prompt` added to the message that started it; `false` starts with no earlier conversation. Either way the child is told `prompt` is the one part of the work it does.\"},\"label\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"A short title for the call’s card.\"},\"prompt\":{\"description\":\"What this run of you works on.\",\"minLength\":1,\"type\":\"string\"},\"schema\":{\"anyOf\":[{\"type\":\"object\"},{\"type\":\"null\"}],\"description\":\"A JSON Schema object: the run finishes by submitting a value of it, returned as `structured`.\"}},\"required\":[\"prompt\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(213,5,15,'context.blob',1,'["golden-host",4,"process-4"]',1767225813000,'{"payload":{"digest":"28d85aa8ad3fc4b558c7b4eb1bae23bb9848bfa2cd8506f6d5e5b9c637afee37","value":"\"const brief = \\\"<goal_round>\\\\nYou are one round of a goal the user approved: work on the objective below yourself, now. What earlier rounds did is in the files and in the previous round''s report below.\\\\nMake as much verified progress as you can, then submit your verdict. Persist when a tool call or command fails: diagnose, adjust and retry.\\\\n- Do not redefine success around a smaller or easier task, and do not substitute a narrower, safer, or merely test-passing solution for the behavior the objective asks for.\\\\n- Treat completion as unproven until you have inspected authoritative evidence (file contents, command output, test results, runtime behavior) for every requirement.\\\\n</goal_round>\\\";\\nconst schema = {\\\"type\\\":\\\"object\\\",\\\"properties\\\":{\\\"status\\\":{\\\"type\\\":\\\"string\\\",\\\"enum\\\":[\\\"continue\\\",\\\"done\\\",\\\"needs_user\\\"],\\\"description\\\":\\\"`done` only once authoritative evidence shows every requirement of the objective holds now; `needs_user` when you cannot go on without the user; `continue` otherwise.\\\"},\\\"report\\\":{\\\"type\\\":\\\"string\\\",\\\"description\\\":\\\"What you did this round, the evidence you inspected and what it shows, and what remains (or what you need from the user). The next round reads it.\\\"}},\\\"required\\\":[\\\"status\\\",\\\"report\\\"],\\\"additionalProperties\\\":false};\\nexport const goal = async (objective, { maxCostUsd }) => {\\n  let report = '''';\\n  let spent = 0;\\n  for (let round = 1; ; round += 1) {\\n    phase(''Round '' + round);\\n    const previous = round === 1 ? '''' : ''\\\\n\\\\n<previous_round round=\\\"'' + (round - 1) + ''\\\">\\\\n'' + report + ''\\\\n</previous_round>'';\\n    const paused = (pause) => ({ outcome: ''paused'', pause, rounds: round, spent, report });\\n    let reply;\\n    try {\\n      reply = await self(brief + ''\\\\n\\\\n<objective>\\\\n'' + objective + ''\\\\n</objective>'' + previous, {\\n        schema, label: ''Round '' + round,\\n      });\\n    } catch (error) {\\n      return paused({ reason: ''round_failed'', error: { name: error.name, message: error.message } });\\n    }\\n    spent = reply.spent;\\n    if (reply.structured == null) return paused({ reason: ''no_verdict'', response: reply.response });\\n    report = reply.structured.report;\\n    if (reply.structured.status === ''done'') return { outcome: ''completed'', rounds: round, spent, report };\\n    if (reply.structured.status === ''needs_user'') return paused({ reason: ''needs_user'' });\\n    if (maxCostUsd > 0 && spent >= maxCostUsd) return paused({ reason: ''spend_cap'', maxCostUsd });\\n  }\\n};\""}}');
INSERT INTO event VALUES(214,5,16,'context.blob',1,'["golden-host",4,"process-4"]',1767225814000,'{"payload":{"digest":"e975156810c38fb3e58ff92d18c106fb3c54f986a56b47f115bfded1109953af","value":"\"\\n/** Run agentName''s document task; resolves to its result, whose\\n *  changes are the files it revised. args takes document_task''s\\n *  fields: prompt, inputFiles, contextFiles, mediaFiles, outputFiles, model,\\n *  attachTeXCount, reflect, autoExtractFigure, autoExtractTikzFigure, autoCompileInputPdf. */\\nexport const revise = (agentName, args = {}) => {\\n  if (typeof tools.document_task !== ''function'')\\n    throw new Error(''revise() calls document_task, which this script is not offered.'');\\n  return tools.document_task({ prompt: '''', ...args, agentName });\\n};\\n\\n/** args for a task over what a finished task produced: each document''s\\n *  latest revision as an input file. A task lists a document once per\\n *  revision, in revision order, so the last copy of each path is the one\\n *  taken, by its absolute path. */\\nexport const from = (result, args = {}) => {\\n  const changes = result?.changes;\\n  if (!Array.isArray(changes))\\n    throw new TypeError(''from() takes the result of a task that ran to its end.'');\\n  const latest = new Map();\\n  for (const change of changes) latest.set(change.path, change.absolutePath);\\n  return { ...args, inputFiles: [...latest.values()] };\\n};\\n\""}}');
INSERT INTO event VALUES(215,5,17,'tools.offered',4,'["golden-host",4,"process-4"]',1767225815000,'{"payload":{"tools":[{"name":"script","digest":"266a6876884ce9ef66eeb1db2a9cf0455c9f977c73d0c9fc67c084ef4fdb4c80","shown":"563b252b1e8e120be9906f0f39ab8c0b8a518265731d7025d501d627901109c5","plugin":"codemode","revision":"builtin","sent":true},{"name":"agent","digest":"8363e59219fb0fd2e4de5fa3a5c1f36801d193f6f6aba4ecc5ffff10bfffa579","shown":"af931a081959b3a5605e02ff5d932cf1c81253c2e9f2e748503c0f0c967c9255","plugin":"multi-agent","revision":"builtin","sent":true},{"name":"document_context","digest":"f863d828574f43e171c14141f6233034cdd09956c5ed6788b11267451b1f4803","shown":"2e136525e5730ec285b62aca6871d0f2c84f9dd68bf68590a12d1b4f811188d4","plugin":"documents","revision":"builtin","sent":true},{"name":"document_extract","digest":"c092ed247ad3e90c8a56628932701fd1eea25950426767f50d4371e74d893b0f","shown":"77c016caef7076a3784a3cca38dff1523aca1c3d4437d65c285fdf996040fdb2","plugin":"documents","revision":"builtin","sent":true},{"name":"document_compile","digest":"e01125425d24d5299b5a20de82aa25844fe6af6b12c0a863719337d94b79ae39","shown":"7bf4e44be734d2f526737156ad8099204875a2c1957f6f4b7152aa98885f3b11","plugin":"documents","revision":"builtin","sent":true},{"name":"document_diff","digest":"3385c24b3d1df23e6fb1312d4104fa5a9a0f07dd6fd57033cc918bc537adb730","shown":"7eeb99b9eed4d292dd3ffb2ba2ea567b5e3ff4ba2f7882e6e72136c8217ba6d5","plugin":"documents","revision":"builtin","sent":true},{"name":"document_review","digest":"23b9e021e445ec27170ea907348b896e3ea3cdffeee48083af4416da78bb7a1c","shown":"234ec8542b5e98b031954478c981b4b1caa43e53a9421c135b5976d5dbcc4163","plugin":"documents","revision":"builtin","sent":true},{"name":"document_propose","digest":"ffecce095e4781a5ca515b1a03eaeec962de235153102e892fa71daf8f0cbe73","shown":"58a974870ba4a8a1280e7e7dbe69e6ef049531b570c2593cdc690209201364cd","plugin":"documents","revision":"builtin","sent":true},{"name":"self","digest":"960684e8811e94d