INSERT INTO event VALUES(407,9,2,'run.config',6,'["golden-host",5,"process-5"]',1767226007000,'{"config":{"inputFiles":[],"contextFiles":[],"mediaFiles":[],"outputFiles":[],"editedFile":null,"agent":"golden_chat","agentSource":"custom","model":"openai/gpt-5.6-sol","instruction":"","displayInstruction":null,"memories":[],"workingDirectory":"/golden/project","cli":null,"delegationAgentScope":null,"outputSchema":null,"script":{"code":"const { goal } = await import(\"builtIn:goal\");\nreturn await goal(\"Answer the golden chat, then stop.\", { maxCostUsd: 5 });","title":"Goal","tools":["plan","codex","bash","memory"],"timeoutMs":86400000,"kind":"background"}}}');
